ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  messageId: (payload.message.messageId default ("msg-" ++ (now() as String {format: "yyyyMMddHHmmss"}))),
  contextId: payload.contextId default ("ctx-office-" ++ (now() as String {format: "yyyyMMdd"})),
  role: "agent",
  parts: [
    { kind: "text", text: payload.response }
  ],
  kind: "message",
  metadata: {}
}
